import java.util.*;

public class SolutionTest {
    public static void main(String[] args) {
        int[] input = {3, 1, 2};
        Solution.SortTrace trace = Solution.traceDescending(input);
        arrayEq(new int[]{3, 2, 1}, trace.getSorted());
        List<int[]> passes = trace.getPasses();
        eq(2, passes.size());
        arrayEq(new int[]{3, 2, 1}, passes.get(0));
        arrayEq(new int[]{3, 2, 1}, passes.get(1));
        arrayEq(new int[]{3, 1, 2}, input);
        expectUOE(() -> passes.add(new int[0]));

        int[] sortedCopy = trace.getSorted();
        sortedCopy[0] = -99;
        arrayEq(new int[]{3, 2, 1}, trace.getSorted());
        int[] passCopy = passes.get(0);
        passCopy[0] = -88;
        arrayEq(new int[]{3, 2, 1}, trace.getPasses().get(0));

        Solution.SortTrace already = Solution.traceDescending(new int[]{5, 5, -1});
        eq(1, already.getPasses().size());
        arrayEq(new int[]{5, 5, -1}, already.getPasses().get(0));

        Solution.SortTrace mixed = Solution.traceDescending(new int[]{Integer.MIN_VALUE, 0, Integer.MAX_VALUE});
        arrayEq(new int[]{Integer.MAX_VALUE, 0, Integer.MIN_VALUE}, mixed.getSorted());
        check(mixed.getPasses().size() >= 1, "missing passes");

        check(Solution.traceDescending(new int[0]).getPasses().isEmpty(), "empty array should have no passes");
        check(Solution.traceDescending(new int[]{7}).getPasses().isEmpty(), "singleton should have no passes");
        arrayEq(new int[]{7}, Solution.traceDescending(new int[]{7}).getSorted());
        expectIAE(() -> Solution.traceDescending(null));
    }

    private static void arrayEq(int[] expected, int[] actual) {
        if (!Arrays.equals(expected, actual)) throw new AssertionError("expected=" + Arrays.toString(expected) + " actual=" + Arrays.toString(actual));
    }

    private static void eq(int expected, int actual) {
        if (expected != actual) throw new AssertionError("expected=" + expected + " actual=" + actual);
    }

    private static void expectIAE(Runnable action) {
        try { action.run(); throw new AssertionError("expected IllegalArgumentException"); }
        catch (IllegalArgumentException expected) { }
    }

    private static void expectUOE(Runnable action) {
        try { action.run(); throw new AssertionError("expected UnsupportedOperationException"); }
        catch (UnsupportedOperationException expected) { }
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }
}

